INSERT INTO review (review_id, user_id, food_item_id, rating, comment, created_at, updated_at) VALUES
    (1, 3, 1,  5, 'Perfectly peppery and silky. Easily the best pasta I have had in town.', '2026-10-22 12:00:00', '2026-10-22 12:00:00'),
    (2, 4, 3,  4, 'Light and not too sweet. Would order again.',                             '2026-10-09 12:00:00', '2026-10-09 12:00:00'),
    (3, 5, 4,  5, 'Fresh tortillas and bright salsa made this a great lunch.',               '2026-10-18 12:00:00', '2026-10-18 12:00:00'),
    (4, 4, 7,  4, 'Crunchy, flaky, and generous. The patio view is a bonus.',                '2026-09-30 12:00:00', '2026-09-30 12:00:00'),
    (5, 3, 10, 4, 'Relaxed atmosphere, generous portions, and excellent coffee.',            '2026-09-29 12:00:00', '2026-09-29 12:00:00'),
    (6, 5, 13, 5, 'Rich broth with real heat. The noodles had a great chew.',                '2026-10-02 12:00:00', '2026-10-02 12:00:00'),
    (7, 3, 16, 5, 'The crust was blistered and smoky, and the basil tasted incredibly fresh.', '2026-10-03 12:00:00', '2026-10-03 12:00:00'),
    (8, 4, 17, 4, 'Great balance of savory sausage and sweet roasted peppers.', '2026-10-04 12:00:00', '2026-10-04 12:00:00'),
    (9, 5, 19, 5, 'Tender chicken and a rich sauce with just the right amount of spice.', '2026-10-05 12:00:00', '2026-10-05 12:00:00'),
    (10, 3, 21, 4, 'Soft, warm naan that was perfect for scooping up the curry.', '2026-10-06 12:00:00', '2026-10-06 12:00:00'),
    (11, 4, 22, 5, 'The green chile gives this burger a delicious local twist.', '2026-10-07 12:00:00', '2026-10-07 12:00:00'),
    (12, 5, 24, 4, 'Silky chocolate filling and a really nice flaky crust.', '2026-10-08 12:00:00', '2026-10-08 12:00:00'),
    (13, 3, 25, 5, 'The lamb was beautifully grilled, and the yogurt sauce was bright and cool.', '2026-10-09 12:00:00', '2026-10-09 12:00:00'),
    (14, 4, 27, 5, 'Crisp, nutty layers without being overly sweet.', '2026-10-10 12:00:00', '2026-10-10 12:00:00'),
    (15, 5, 28, 4, 'Deep, comforting broth and perfectly cooked noodles.', '2026-10-11 12:00:00', '2026-10-11 12:00:00'),
    (16, 3, 30, 5, 'Crispy bottoms and a flavorful ginger dipping sauce.', '2026-10-12 12:00:00', '2026-10-12 12:00:00'),
    (17, 4, 31, 5, 'Smoky, tender brisket with a great bark and generous sides.', '2026-10-13 12:00:00', '2026-10-13 12:00:00'),
    (18, 5, 33, 4, 'Warm, buttery cornbread with just a touch of sweetness.', '2026-10-14 12:00:00', '2026-10-14 12:00:00'),
    (19, 3, 34, 4, 'Fresh toppings and hearty sourdough made this a satisfying breakfast.', '2026-10-15 12:00:00', '2026-10-15 12:00:00'),
    (20, 4, 36, 5, 'Lovely floral aroma without overpowering the espresso.', '2026-10-16 12:00:00', '2026-10-16 12:00:00'),
    (21, 5, 37, 5, 'Flaky outside, soft inside, and plenty of almond filling.', '2026-10-17 12:00:00', '2026-10-17 12:00:00'),
    (22, 3, 39, 4, 'A generous serving of salmon on a chewy, fresh bagel.', '2026-10-18 12:00:00', '2026-10-18 12:00:00'),
    (23, 4, 40, 5, 'Packed with tender steak and bright salsa. Great value, too.', '2026-10-19 12:00:00', '2026-10-19 12:00:00'),
    (24, 5, 42, 4, 'Fresh guacamole with plenty of lime and crisp chips.', '2026-10-20 12:00:00', '2026-10-20 12:00:00'),
    (25, 3, 43, 5, 'The broth was fragrant and warming, with plenty of fresh herbs.', '2026-10-21 12:00:00', '2026-10-21 12:00:00'),
    (26, 4, 45, 4, 'Fresh, delicate rolls and a delicious peanut dipping sauce.', '2026-10-22 12:00:00', '2026-10-22 12:00:00'),
    (27, 5, 46, 5, 'Beautifully fresh salmon and rice seasoned just right.', '2026-10-23 12:00:00', '2026-10-23 12:00:00'),
    (28, 3, 47, 4, 'A generous roll with crunchy tempura and creamy avocado.', '2026-10-24 12:00:00', '2026-10-24 12:00:00'),
    (29, 4, 49, 5, 'Crispy falafel with cool vegetables and smooth tahini.', '2026-10-25 12:00:00', '2026-10-25 12:00:00'),
    (30, 5, 50, 4, 'Well-seasoned chicken and a filling bowl with excellent garlic sauce.', '2026-10-26 12:00:00', '2026-10-26 12:00:00'),
    (31, 3, 52, 5, 'The bison was juicy, and the cheddar and onions were a perfect match.', '2026-10-27 12:00:00', '2026-10-27 12:00:00'),
    (32, 4, 54, 4, 'Rich maple filling and toasted pecans make this a great finish.', '2026-10-28 12:00:00', '2026-10-28 12:00:00'),
    (33, 5, 55, 5, 'Deep wine sauce and tender chicken made this a memorable dinner.', '2026-10-29 12:00:00', '2026-10-29 12:00:00'),
    (34, 3, 56, 4, 'Comforting soup with a generous layer of melted Gruyere.', '2026-10-30 12:00:00', '2026-10-30 12:00:00'),
    (35, 4, 58, 5, 'Tangy, savory and nicely balanced, with a good squeeze of lime.', '2026-10-31 12:00:00', '2026-10-31 12:00:00'),
    (36, 5, 60, 4, 'Sweet ripe mango with creamy coconut rice. A lovely dessert.', '2026-11-01 12:00:00', '2026-11-01 12:00:00'),
    (37, 3, 61, 5, 'Smoky jackfruit and crunchy slaw make these tacos really satisfying.', '2026-11-02 12:00:00', '2026-11-02 12:00:00'),
    (38, 4, 63, 4, 'Light, creamy and topped with fresh berries.', '2026-11-03 12:00:00', '2026-11-03 12:00:00'),
    (39, 5, 64, 4, 'Savory and filling, with a tender crepe and plenty of Gruyere.', '2026-11-04 12:00:00', '2026-11-04 12:00:00'),
    (40, 3, 65, 5, 'A perfect sweet crepe: warm chocolate, fresh berries and crisp edges.', '2026-11-05 12:00:00', '2026-11-05 12:00:00'),
    (41, 4, 67, 5, 'Cooked exactly as requested, with rich herb butter and crisp potatoes.', '2026-11-06 12:00:00', '2026-11-06 12:00:00'),
    (42, 5, 69, 4, 'Creamy cheesecake with a pleasantly tart fruit topping.', '2026-11-07 12:00:00', '2026-11-07 12:00:00'),
    (43, 3, 70, 5, 'Carefully folded dumplings with a savory broth inside.', '2026-11-08 12:00:00', '2026-11-08 12:00:00'),
    (44, 4, 71, 4, 'The chili sesame sauce had great flavor and a satisfying kick.', '2026-11-09 12:00:00', '2026-11-09 12:00:00'),
    (45, 5, 73, 5, 'Bright citrus glaze complements the salmon without overpowering it.', '2026-11-10 12:00:00', '2026-11-10 12:00:00'),
    (46, 3, 75, 4, 'Tart, creamy filling in a crisp crust. A refreshing dessert.', '2026-11-11 12:00:00', '2026-11-11 12:00:00');
